import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

const apiBaseUrl = String.fromEnvironment('API_BASE_URL', defaultValue: 'http://localhost:8000/api/v1');

class ApiClient {
  String? accessToken;
  Map<String,String> get headers => {'Content-Type':'application/json',if(accessToken!=null)'Authorization':'Bearer $accessToken'};
  String error(http.Response r){try{final d=jsonDecode(r.body);if(d is Map&&d.isNotEmpty){final v=d.values.first;return v is List?v.first.toString():v.toString();}}catch(_){}return 'خطا در ارتباط با سرور (${r.statusCode})';}
  Future<void> register(String username,String phone,String firstName,String lastName,String password)async{final r=await http.post(Uri.parse('$apiBaseUrl/auth/register/'),headers:headers,body:jsonEncode({'username':username,'phone':phone,'first_name':firstName,'last_name':lastName,'password':password}));if(r.statusCode!=201)throw Exception(error(r));}
  Future<void> login(String username,String password)async{final r=await http.post(Uri.parse('$apiBaseUrl/auth/token/'),headers:headers,body:jsonEncode({'username':username,'password':password}));if(r.statusCode!=200)throw Exception(error(r));accessToken=jsonDecode(r.body)['access'];}
  Future<List<Map<String,dynamic>>> vehicles()async{final r=await http.get(Uri.parse('$apiBaseUrl/vehicles/'),headers:headers);if(r.statusCode!=200)throw Exception(error(r));return List<Map<String,dynamic>>.from(jsonDecode(r.body));}
  Future<Map<String,dynamic>> addVehicle({required String nickname,required String make,required String model,required int year,required int odometer,required String fuelType})async{final r=await http.post(Uri.parse('$apiBaseUrl/vehicles/'),headers:headers,body:jsonEncode({'nickname':nickname,'make':make,'model':model,'year':year,'current_odometer_km':odometer,'fuel_type':fuelType}));if(r.statusCode!=201)throw Exception(error(r));return Map<String,dynamic>.from(jsonDecode(r.body));}
}
void main()=>runApp(const App());
class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'دستیار خودرو',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xFF10A7A0)),scaffoldBackgroundColor:const Color(0xFFF5F7FA)),home:LoginPage(api:ApiClient()));}
class LoginPage extends StatefulWidget{const LoginPage({super.key,required this.api});final ApiClient api;@override State<LoginPage>createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final username=TextEditingController(),phone=TextEditingController(),firstName=TextEditingController(),lastName=TextEditingController(),password=TextEditingController();bool reg=false,busy=false;Future<void>submit()async{final u=username.text.trim(),p=phone.text.trim().replaceAll(' ','');if(reg&&(u.isEmpty||firstName.text.trim().isEmpty||lastName.text.trim().isEmpty||!RegExp(r'^09\d{9}$').hasMatch(p))){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('همه اطلاعات ثبت‌نام الزامی است و شماره موبایل باید معتبر باشد.')));return;}if(u.isEmpty||password.text.length<8){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('نام کاربری و رمز عبور حداقل ۸ کاراکتر وارد کنید.')));return;}setState(()=>busy=true);try{if(reg)await widget.api.register(u,p,firstName.text.trim(),lastName.text.trim(),password.text);await widget.api.login(u,password.text);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Dashboard(api:widget.api)));}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>busy=false);}}InputDecoration dec(String l,IconData i)=>InputDecoration(labelText:'$l *',prefixIcon:Icon(i),border:const OutlineInputBorder());@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(body:Center(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:430),child:Padding(padding:const EdgeInsets.all(24),child:Card(child:Padding(padding:const EdgeInsets.all(28),child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.directions_car_filled_rounded,size:54,color:Color(0xFF10A7A0)),const SizedBox(height:12),const Text('دستیار خودرو',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:6),Text(reg?'ساخت حساب کاربری':'ورود به حساب کاربری',style:const TextStyle(color:Colors.grey)),const SizedBox(height:28),TextField(controller:username,decoration:dec('نام کاربری',Icons.person_outline)),if(reg)...[const SizedBox(height:12),TextField(controller:firstName,decoration:dec('نام',Icons.badge_outlined)),const SizedBox(height:12),TextField(controller:lastName,decoration:dec('نام خانوادگی',Icons.badge)),const SizedBox(height:12),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:dec('شماره موبایل',Icons.phone_android_outlined))],const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:dec('رمز عبور',Icons.lock_outline)),const SizedBox(height:18),SizedBox(width:double.infinity,height:50,child:FilledButton(onPressed:busy?null:submit,child:Text(busy?'در حال اتصال...':reg?'ساخت حساب':'ورود'))),TextButton(onPressed:busy?null:()=>setState(()=>reg=!reg),child:Text(reg?'حساب دارم؛ ورود':'حساب ندارم؛ ثبت‌نام'))]))))))));}
class Dashboard extends StatefulWidget{const Dashboard({super.key,required this.api});final ApiClient api;@override State<Dashboard>createState()=>_DashboardState();}
class _DashboardState extends State<Dashboard>{List<Map<String,dynamic>>cars=[];bool loading=true;String?err;@override void initState(){super.initState();load();}Future<void>load()async{try{final d=await widget.api.vehicles();if(mounted)setState(()=>cars=d);}catch(x){if(mounted)setState(()=>err=x.toString().replaceFirst('Exception: ',''));}finally{if(mounted)setState(()=>loading=false);}}Future<void>add()async{final car=await showDialog<Map<String,dynamic>>(context:context,builder:(_)=>AddVehicle(api:widget.api));if(car!=null&&mounted){setState(()=>cars.insert(0,car));ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('خودرو با موفقیت ثبت شد.')));}}@override Widget build(BuildContext c)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:const Text('دستیار خودرو',style:TextStyle(fontWeight:FontWeight.w900)),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh_rounded))]),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('خودروهای من',style:TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:12),if(loading)const Center(child:CircularProgressIndicator())else if(err!=null)Text('خطا: $err')else if(cars.isEmpty)const Text('هنوز خودرویی ثبت نکرده‌ای.')else ...cars.map((v)=>CarCard(car:v))]));}}
class CarCard extends StatelessWidget{const CarCard({super.key,required this.car});final Map<String,dynamic>car;@override Widget build(BuildContext c)=>Card(child:ListTile(leading:const Icon(Icons.directions_car_filled_rounded),title:Text('${car['make']} ${car['model']}'),subtitle:Text('${car['nickname']} • ${car['current_odometer_km']} کیلومتر')));}
class AddVehicle extends StatefulWidget{const AddVehicle({super.key,required this.api});final ApiClient api;@override State<AddVehicle>createState()=>_AddVehicleState();}
class _AddVehicleState extends State<AddVehicle>{final n=TextEditingController(),m=TextEditingController(),mo=TextEditingController(),y=TextEditingController(),o=TextEditingController();String fuel='petrol';bool busy=false;Future<void>save()async{if(m.text.isEmpty||mo.text.isEmpty||o.text.isEmpty)return;final od=int.tryParse(o.text);if(od==null||od<0)return;setState(()=>busy=true);try{final v=await widget.api.addVehicle(nickname:n.text.isEmpty?'خودروی من':n.text,make:m.text,model:mo.text,year:int.tryParse(y.text)??0,odometer:od,fuelType:fuel);if(mounted)Navigator.pop(context,v);}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x.toString().replaceFirst('Exception: ',''))));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext c)=>AlertDialog(title:const Text('افزودن خودرو'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'نام خودرو')),const SizedBox(height:10),TextField(controller:m,decoration:const InputDecoration(labelText:'برند *')),const SizedBox(height:10),TextField(controller:mo,decoration:const InputDecoration(labelText:'مدل *')),const SizedBox(height:10),TextField(controller:y,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سال')),const SizedBox(height:10),TextField(controller:o,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'کیلومتر فعلی *'))]),actions:[TextButton(onPressed:busy?null:()=>Navigator.pop(context),child:const Text('انصراف')),FilledButton(onPressed:busy?null:save,child:Text(busy?'در حال ثبت...':'ثبت خودرو'))]);}
